from .units import g_to_kg, kg_to_g

LIGHT_G = 500  # 0.500 kg
MEDIUM_G = 2000  # 2.000 kg


def average_weight_kg(order):
    units = sum(item.qty for item in order.items)
    if units == 0:
        return "0.000"
    total_g = sum(kg_to_g(item.line_weight_kg()) for item in order.items)
    # total_g / units is the average in thousandths of a kg; round it half to even, exactly.
    quotient, remainder = divmod(total_g, units)
    if 2 * remainder > units or (2 * remainder == units and quotient % 2 == 1):
        quotient += 1
    return g_to_kg(quotient)


def heaviest(order, n=3):
    return sorted(order.items, key=lambda item: (-kg_to_g(item.weight_kg), item.sku))[:n]


def weight_bands(order):
    bands = {"light": 0, "medium": 0, "heavy": 0}
    for item in order.items:
        grams = kg_to_g(item.weight_kg)
        if grams <= LIGHT_G:
            bands["light"] += item.qty
        elif grams <= MEDIUM_G:
            bands["medium"] += item.qty
        else:
            bands["heavy"] += item.qty
    return bands

