import contextlib
import io
import json
import os
import tempfile
import unittest

from shipcalc import cache, cli, export, format as fmt, limits, reports, storage
from shipcalc.calc import order_weight_kg
from shipcalc.models import Item, Order
from shipcalc.units import WeightError, g_to_kg, kg_to_g, normalize_kg
from shipcalc.validate import validate_item


class UnitsTest(unittest.TestCase):
    def test_normalize_pads_and_keeps_three_places(self):
        self.assertEqual(normalize_kg("2"), "2.000")
        self.assertEqual(normalize_kg("0.250"), "0.250")
        self.assertEqual(normalize_kg("1000.000"), "1000.000")

    def test_rounds_half_to_even(self):
        self.assertEqual(normalize_kg("1.0005"), "1.000")
        self.assertEqual(normalize_kg("1.0015"), "1.002")
        self.assertEqual(normalize_kg("2.0025"), "2.002")
        self.assertEqual(normalize_kg("1.2345"), "1.234")
        self.assertEqual(normalize_kg("1.2346"), "1.235")

    def test_rejects_invalid_strings(self):
        for bad in ["-1", "+1", "1e3", "nan", "inf", "", " 1", "1 ", "1,5", "1.", ".5", ".", "١"]:
            with self.subTest(bad=bad), self.assertRaises(WeightError):
                normalize_kg(bad)

    def test_rejects_non_strings_with_repr_message(self):
        for bad in [1, 1.5, True, None]:
            with self.subTest(bad=bad), self.assertRaises(WeightError) as ctx:
                normalize_kg(bad)
            self.assertEqual(str(ctx.exception), f"invalid weight: {bad!r}")
        with self.assertRaises(WeightError) as ctx:
            normalize_kg("abc")
        self.assertEqual(str(ctx.exception), "invalid weight: 'abc'")

    def test_weight_error_is_value_error(self):
        self.assertTrue(issubclass(WeightError, ValueError))

    def test_kg_and_grams_conversions(self):
        self.assertEqual(kg_to_g("1.25"), 1250)
        self.assertEqual(g_to_kg(1250), "1.250")
        self.assertEqual(g_to_kg(0), "0.000")
        for bad in [-1, True, 1.0, "1500"]:
            with self.subTest(bad=bad), self.assertRaises(WeightError):
                g_to_kg(bad)


class ModelTest(unittest.TestCase):
    def test_item_normalises_weight(self):
        self.assertEqual(Item("A", "1.0005").weight_kg, "1.000")

    def test_invalid_item_weight_is_weight_error(self):
        with self.assertRaises(WeightError):
            Item("A", "1.")


class ValidateTest(unittest.TestCase):
    def valid(self, **over):
        data = {"sku": "A", "weight_kg": "0.500", "qty": 1}
        data.update(over)
        return data

    def test_valid(self):
        self.assertEqual(validate_item(self.valid()), [])

    def test_range_applies_after_rounding(self):
        self.assertEqual(validate_item(self.valid(weight_kg="0.0004")), ["weight_kg: out of range 0.001..1000.000"])
        self.assertEqual(validate_item(self.valid(weight_kg="1000.0004")), [])

    def test_invalid_weight_is_reported_on_weight_kg(self):
        problems = validate_item(self.valid(weight_kg="1,5"))
        self.assertEqual(len(problems), 1)
        self.assertTrue(problems[0].startswith("weight_kg: "))

    def test_missing_weight_kg(self):
        data = self.valid()
        del data["weight_kg"]
        data["weight_g"] = 500
        self.assertIn("weight_kg: missing", validate_item(data))


class ReportsTest(unittest.TestCase):
    def test_average_rounds_half_to_even(self):
        order = Order([Item("A", "1.000", 3)])
        self.assertEqual(reports.average_weight_kg(order), "1.000")
        self.assertEqual(reports.average_weight_kg(Order([Item("A", "0.001", 2)])), "0.001")
        self.assertEqual(reports.average_weight_kg(Order([Item("A", "0.005", 2)])), "0.002")
        self.assertEqual(reports.average_weight_kg(Order([Item("A", "0.007", 2)])), "0.004")
        self.assertEqual(reports.average_weight_kg(Order([Item("A", "1.900", 1), Item("B", "0.001", 2)])), "0.634")

    def test_average_of_empty_order(self):
        self.assertEqual(reports.average_weight_kg(Order()), "0.000")

    def test_heaviest_and_bands(self):
        order = Order([Item("B", "0.500", 2), Item("A", "0.500"), Item("C", "2.000"), Item("D", "2.001")])
        self.assertEqual([i.sku for i in reports.heaviest(order, 3)], ["D", "C", "A"])
        self.assertEqual(reports.weight_bands(order), {"light": 3, "medium": 1, "heavy": 1})


class LimitsTest(unittest.TestCase):
    def test_exact_carrier_limit_is_accepted(self):
        self.assertEqual(limits.check_total_kg("2147483.647"), "2147483.647")
        self.assertEqual(order_weight_kg(Order([Item("A", "2147483.647")])), "2147483.647")

    def test_over_carrier_limit_is_rejected(self):
        with self.assertRaises(WeightError):
            limits.check_total_kg("2147483.648")
        with self.assertRaises(WeightError):
            order_weight_kg(Order([Item("A", "1000000.000", 3)]))

    def test_empty_order_weight(self):
        self.assertEqual(order_weight_kg(Order()), "0.000")


class ExportTest(unittest.TestCase):
    def test_csv_and_payload_stay_in_grams(self):
        order = Order([Item("MUG-01", "0.350", 2), Item("BOOK-07", "1.200")])
        self.assertEqual(export.to_csv(order), "sku,weight_g,qty\nMUG-01,350,2\nBOOK-07,1200,1\n")
        payload = export.carrier_payload(order)
        self.assertEqual(payload, {"weight_g": 1900, "parcels": 1})
        self.assertIs(type(payload["weight_g"]), int)


class FormatTest(unittest.TestCase):
    def test_format_weight(self):
        self.assertEqual(fmt.format_weight("0.250"), "0.250 kg")
        self.assertEqual(fmt.format_weight("12.000"), "12.000 kg")


class CacheTest(unittest.TestCase):
    def test_quote_key_uses_v2_and_kg(self):
        order = Order([Item("A", "0.250", 2)])
        self.assertEqual(cache.quote_key(order, "eu"), "quote:v2:eu:0.500:1")


class StorageTest(unittest.TestCase):
    def setUp(self):
        self.dir = tempfile.TemporaryDirectory()
        self.path = os.path.join(self.dir.name, "order.json")

    def tearDown(self):
        self.dir.cleanup()

    def test_save_then_load_schema_2(self):
        storage.save(Order([Item("A", "0.250", 2)]), self.path)
        with open(self.path, encoding="utf-8") as handle:
            data = json.load(handle)
        self.assertEqual(data["schema"], 2)
        self.assertEqual(data["items"], [{"sku": "A", "weight_kg": "0.250", "qty": 2}])
        self.assertEqual(storage.load(self.path).items[0].weight_kg, "0.250")

    def test_loads_schema_1_exactly(self):
        with open(self.path, "w", encoding="utf-8") as handle:
            json.dump({"schema": 1, "items": [{"sku": "A", "weight_g": 1250, "qty": 2}]}, handle)
        item = storage.load(self.path).items[0]
        self.assertEqual((item.weight_kg, item.qty), ("1.250", 2))

    def test_invalid_weight_in_either_schema(self):
        for doc in [
            {"schema": 1, "items": [{"sku": "A", "weight_g": "1250"}]},
            {"schema": 2, "items": [{"sku": "A", "weight_kg": "1,5"}]},
        ]:
            with self.subTest(doc=doc), open(self.path, "w", encoding="utf-8") as handle:
                json.dump(doc, handle)
            with self.assertRaises(WeightError):
                storage.load(self.path)

    def test_unknown_schema(self):
        with open(self.path, "w", encoding="utf-8") as handle:
            json.dump({"schema": 3, "items": []}, handle)
        with self.assertRaises(ValueError):
            storage.load(self.path)


class CliTest(unittest.TestCase):
    def setUp(self):
        self.dir = tempfile.TemporaryDirectory()
        self.path = os.path.join(self.dir.name, "order.json")
        storage.save(Order(), self.path)

    def tearDown(self):
        self.dir.cleanup()

    def run_cli(self, *args):
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            code = cli.main(list(args))
        return code, out.getvalue(), err.getvalue()

    def test_add_then_show(self):
        self.assertEqual(self.run_cli("add", self.path, "MUG-01", "0.25", "2")[0], 0)
        code, out, _ = self.run_cli("show", self.path)
        self.assertEqual(code, 0)
        self.assertIn("total weight: 0.500 kg", out)

    def test_invalid_weight_exits_2(self):
        code, _, err = self.run_cli("add", self.path, "MUG-01", "1,5", "1")
        self.assertEqual(code, 2)
        self.assertEqual(err, "error: invalid weight: '1,5'\n")


if __name__ == "__main__":
    unittest.main()

